codeExamples.code:
-- Wrap migration in a transaction block (PostgreSQL supports Transactional DDL!)
BEGIN TRANSACTION;

-- Step 1: Safely add a new column with a default value for existing rows
ALTER TABLE orders 
ADD COLUMN IF NOT EXISTS payment_method VARCHAR(50) NOT NULL DEFAULT 'Credit Card';

-- Step 2: Rename an outdated column cleanly
ALTER TABLE orders 
RENAME COLUMN order_timestamp TO created_at;

-- Step 3: Modify column type with explicit USING conversion expression
ALTER TABLE orders 
ALTER COLUMN order_status TYPE VARCHAR(50);

-- Step 4: Drop legacy temporary staging table using TRUNCATE then DROP
TRUNCATE TABLE orders_high_value_archive; -- Instantly deallocates disk pages
DROP TABLE IF EXISTS orders_high_value_archive CASCADE;

COMMIT; -- Commit schema migration atomically to disk!

practiceExercise.solutionCode:
-- Exercise 1 Comparison Answers:
-- a. WHERE Clause    : Supported ONLY by DELETE FROM. Not supported by DROP or TRUNCATE.
-- b. Execution Speed : TRUNCATE and DROP are instant (deallocate disk pages). DELETE is slow (scans row-by-row).
-- c. Sequence Reset  : TRUNCATE resets auto-increment counters back to 1. DELETE does NOT reset counters.

-- Exercise 2 DDL Script Answer:
BEGIN TRANSACTION;

-- Step a: Create products_v1 table with generated stored column
CREATE TABLE products_v1 (
    product_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    cost NUMERIC(10, 2) NOT NULL,
    tax NUMERIC(10, 2) NOT NULL,
    total_cost NUMERIC(10, 2) GENERATED ALWAYS AS (cost + tax) STORED
);

-- Step b: Alter table to add category column with default value
ALTER TABLE products_v1 
ADD COLUMN category VARCHAR(50) NOT NULL DEFAULT 'General';

-- Step c: Rename table to products_master
ALTER TABLE products_v1 RENAME TO products_master;

COMMIT;

codeExamples.code:
-- 1. Deferred Constraint Validation inside a Transaction Block
CREATE TABLE authors (
    author_id INT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    featured_book_id INT -- Circular reference to books table
);

CREATE TABLE books (
    book_id INT PRIMARY KEY,
    title VARCHAR(150) NOT NULL,
    author_id INT NOT NULL
);

-- Add Deferrable Foreign Key constraint to solve circular insertion dependency
ALTER TABLE authors 
ADD CONSTRAINT fk_authors_books 
FOREIGN KEY (featured_book_id) REFERENCES books(book_id)
DEFERRABLE INITIALLY DEFERRED;

BEGIN TRANSACTION;
-- Deferred validation allows inserting author before book exists within the same transaction!
INSERT INTO authors (author_id, name, featured_book_id) VALUES (1, 'Dr. Edgar Codd', 101);
INSERT INTO books (book_id, title, author_id) VALUES (101, 'Relational Database Model', 1);
COMMIT; -- Engine validates foreign key integrity at COMMIT time!

-- 2. Zero-Lock PostgreSQL Migration Pattern for 10M Row Tables
-- Step 1: Add constraint without validating existing rows (Split-second lock!)
ALTER TABLE books 
ADD CONSTRAINT fk_books_authors 
FOREIGN KEY (author_id) REFERENCES authors(author_id) 
NOT VALID;

-- Step 2: Validate existing rows in background without blocking production reads/writes
ALTER TABLE books VALIDATE CONSTRAINT fk_books_authors;

-- Bank Account Transfer with Pessimistic Row Locking and Savepoints
BEGIN TRANSACTION;

-- Step 1: Explicit Row Locking (SELECT FOR UPDATE) to prevent concurrent balance modifications
SELECT account_id, balance 
FROM bank_accounts 
WHERE account_id IN (101, 202) 
FOR UPDATE;

-- Step 2: Deduct $500 from Sender (Account 101)
UPDATE bank_accounts 
SET balance = balance - 500.00 
WHERE account_id = 101 AND balance >= 500.00;

-- Set a Savepoint before secondary operation
SAVEPOINT transfer_deducted;

-- Step 3: Credit $500 to Recipient (Account 202)
UPDATE bank_accounts 
SET balance = balance + 500.00 
WHERE account_id = 202;

-- Step 4: Verify recipient update succeeded; if failed, rollback to savepoint!
-- Otherwise, commit the atomic transaction permanently
COMMIT;

-- 1. Provision Restricted Role-Based Application User (DCL)
CREATE ROLE analyst_read_only WITH LOGIN PASSWORD 'AnalystPass2026!';

-- Grant schema access and read-only SELECT permissions
GRANT USAGE ON SCHEMA public TO analyst_read_only;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO analyst_read_only;
REVOKE INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public FROM analyst_read_only;

-- 2. Enable PostgreSQL Row-Level Security (RLS) for Multi-Tenant Data Isolation
ALTER TABLE customer_orders ENABLE ROW LEVEL SECURITY;

-- Create policy restricting users to viewing ONLY their own tenant records!
CREATE POLICY tenant_order_isolation_policy ON customer_orders
    FOR ALL
    TO app_service_user
    USING (tenant_id = current_setting('app.current_tenant_id'));

